void SimpleTrackedObjectMergerNode::onTimer()
{
  rclcpp::Time latest_stamp{0, 0, this->get_clock()->get_clock_type()};
  bool has_valid_input = false;

  for (size_t i = 0; i < input_topic_size_; i++) {
    if (objects_data_.at(i)) {
      const auto & stamp = objects_data_.at(i)->header.stamp;
      if (!has_valid_input || rclcpp::Time(stamp) > latest_stamp) {
        latest_stamp = stamp;
        has_valid_input = true;
      }
    }
  }

  TrackedObjects output_objects;
  output_objects.header.frame_id = node_param_.new_frame_id;

  if (!has_valid_input) {
    output_objects.header.stamp = this->now();
    pub_objects_->publish(output_objects);
    cleanupUUIDMap();
    return;
  }

  output_objects.header.stamp = latest_stamp;

  constexpr double throttle_interval = 3.0;  // seconds
  const rclcpp::Time now = this->now();

  static std::vector<rclcpp::Time> last_log_times;
  if (last_log_times.size() != input_topic_size_) {
    last_log_times.assign(input_topic_size_, now);
  }

  for (size_t i = 0; i < input_topic_size_; i++) {
    if (!objects_data_.at(i)) {
      continue;
    }

    double time_diff =
      rclcpp::Time(objects_data_.at(i)->header.stamp).seconds() - latest_stamp.seconds();
    if (std::abs(time_diff) < node_param_.timeout_threshold) {
      TrackedObjects::SharedPtr transformed_objects;
      if (node_param_.new_frame_id == objects_data_.at(i)->header.frame_id) {
        transformed_objects = std::make_shared<TrackedObjects>(*objects_data_.at(i));
      } else {
        auto transform = transform_listener_->get_transform(
          node_param_.new_frame_id, objects_data_.at(i)->header.frame_id,
          objects_data_.at(i)->header.stamp, rclcpp::Duration::from_seconds(0.01));
        if (!transform) {
          continue;
        }
        transformed_objects =
          getTransformedObjects(objects_data_.at(i), node_param_.new_frame_id, transform);
      }
      for (auto & object : transformed_objects->objects) {
        mapUUID(object, i);
        output_objects.objects.push_back(object);
      }
    } else if (shouldLogThrottle(i, now, last_log_times, throttle_interval)) {
      RCLCPP_INFO(
        get_logger(), "Topic of %s is timeout by %f sec", node_param_.topic_names.at(i).c_str(),
        time_diff);
    }
  }

  pub_objects_->publish(output_objects);
  cleanupUUIDMap();
}

geometry_msgs::msg::TransformStamped::ConstSharedPtr get_transform(
  const std::string & from, const std::string & to, const rclcpp::Time & time,
  const rclcpp::Duration & duration)
{
  geometry_msgs::msg::TransformStamped tf;
  try {
    tf = tf_buffer_->lookupTransform(from, to, time, duration);
  } catch (tf2::TransformException & ex) {
    RCLCPP_WARN_THROTTLE(
      logger_, *clock_, 5000, "failed to get transform from %s to %s: %s", from.c_str(),
      to.c_str(), ex.what());
    return {};
  }

  return std::make_shared<const geometry_msgs::msg::TransformStamped>(tf);
}

typename ObjsMsgType::SharedPtr SimpleObjectMergerBase<ObjsMsgType>::getTransformedObjects(
  typename ObjsMsgType::ConstSharedPtr objects, const std::string & target_frame_id,
  geometry_msgs::msg::TransformStamped::ConstSharedPtr transform)
{
  typename ObjsMsgType::SharedPtr output_objects = std::make_shared<ObjsMsgType>(*objects);

  if (objects->header.frame_id == target_frame_id) {
    return output_objects;
  }

  output_objects->header.frame_id = target_frame_id;
  for (auto & object : output_objects->objects) {
    // convert by tf
    geometry_msgs::msg::PoseStamped pose_stamped{};
    pose_stamped.pose = object.kinematics.pose_with_covariance.pose;
    geometry_msgs::msg::PoseStamped transformed_pose_stamped{};
    tf2::doTransform(pose_stamped, transformed_pose_stamped, *transform);
    object.kinematics.pose_with_covariance.pose = transformed_pose_stamped.pose;
  }

  return output_objects;
}

void SimpleTrackedObjectMergerNode::mapUUID(TrackedObject & object, const int & node_id)
{
  rclcpp::Time now = this->now();

  UUIDMapping & mapping = uuid_mapper_[uuidToString(object.object_id)];
  mapping.last_seen = now;

  // check whether the UUID collides or not.
  if (mapping.pass_through_node_id == -1) {
    // first time of seeing the UUID, no UUID change
    mapping.pass_through_node_id = node_id;
  } else if (mapping.pass_through_node_id == node_id && !mapping.is_mapped_uuid) {
    // when the UUID originate from the node and it is not mapped
    // nothing to do
    ;
  } else {
    // UUID collides
    auto it = mapping.replace_map.find(node_id);
    if (it == mapping.replace_map.end()) {
      unique_identifier_msgs::msg::UUID new_uuid;
      std::string uuid_str;
      generateNewUUID(uuid_mapper_, new_uuid, uuid_str);

      // add the new UUID to the mapper
      UUIDMapping & new_uuid_mapping = uuid_mapper_[uuid_str];
      new_uuid_mapping.pass_through_node_id = node_id;
      new_uuid_mapping.last_seen = now;
      new_uuid_mapping.is_mapped_uuid = true;

      mapping.replace_map[node_id] = new_uuid;
      object.object_id = new_uuid;
    } else {
      object.object_id = it->second;
    }
  }
}

unique_identifier_msgs::msg::UUID generateNewUUID()
{
  static boost::uuids::random_generator generator;
  boost::uuids::uuid boost_uuid = generator();

  unique_identifier_msgs::msg::UUID uuid;
  std::copy(boost_uuid.begin(), boost_uuid.end(), uuid.uuid.begin());

  return uuid;
}

bool SimpleObjectMergerBase<ObjsMsgType>::shouldLogThrottle(
  size_t index, const rclcpp::Time & now, std::vector<rclcpp::Time> & last_log_times,
  double throttle_interval_sec)
{
  if ((now - last_log_times[index]) > rclcpp::Duration::from_seconds(throttle_interval_sec)) {
    last_log_times[index] = now;
    return true;
  }
  return false;
}

void SimpleTrackedObjectMergerNode::cleanupUUIDMap()
{
  rclcpp::Time now = this->now();

  for (auto it = uuid_mapper_.begin(); it != uuid_mapper_.end();) {
    if ((now - it->second.last_seen) > uuid_mapping_cleanup_threshold_) {
      it = uuid_mapper_.erase(it);
    } else {
      ++it;
    }
  }
}
